const syncKey = 'studio/project-sync.json';
const limit = 4_000_000;
const json = (value,status=200) => Response.json(value,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const mime = {html:'text/html',mjs:'text/javascript'};

async function boundedJson(request) {
  if (Number(request.headers.get('content-length'))>limit || !request.body) throw new Error('The project collection exceeds the 4 MB sync limit.');
  const reader=request.body.getReader(), decoder=new TextDecoder();
  let size=0, text='';
  while (true) {
    const {value,done}=await reader.read();
    if(done) break;
    size+=value.byteLength;
    if(size>limit){await reader.cancel();throw new Error('The project collection exceeds the 4 MB sync limit.');}
    text+=decoder.decode(value,{stream:true});
  }
  return JSON.parse(text+decoder.decode());
}

function checkedProjects(projects) {
  if(!Array.isArray(projects)||projects.length>60)throw new Error('Sync supports up to 60 projects.');
  const ids=new Set();
  return projects.map(project=>{
    if(!project || typeof project.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(project.id)||ids.has(project.id)
      ||typeof project.title!=='string'||project.title.length>200||typeof project.brief!=='string'||project.brief.length>15000
      ||typeof project.html!=='string'||project.html.length>450000||!['Simple','Intermediate','Advanced','Expert'].includes(project.level))throw new Error('One project cannot be synced with its current size or format.');
    ids.add(project.id);
    const aliases=Array.isArray(project.aliases)
      ? [...new Set(project.aliases.filter(alias=>typeof alias==='string').map(alias=>alias.trim().slice(0,100)).filter(Boolean))].slice(0,8)
      : [];
    return {id:project.id,title:project.title,brief:project.brief,html:project.html,level:project.level,
      updated:Number.isFinite(project.updated)?project.updated:0,...(aliases.length?{aliases}:{})};
  });
}

async function sync(request,bucket,url) {
  if(request.method==='GET'){
    const entry=await bucket.get(syncKey);
    return json({revision:entry?.httpEtag??null,projects:entry?await entry.json():[]});
  }
  if(request.method!=='PUT')return json({error:'Method not allowed.'},405);
  if(request.headers.get('origin')!==url.origin || !request.headers.get('content-type')?.startsWith('application/json')){
    return json({error:'Open Studio directly to sync projects.'},403);
  }
  const {revision,projects}=await boundedJson(request);
  if(revision!==null && (typeof revision!=='string'||!/^"[a-f0-9]{32}"$/i.test(revision)))return json({error:'Invalid sync revision.'},400);
  const records=checkedProjects(projects);
  const write=await bucket.put(syncKey,JSON.stringify(records),{
    onlyIf:revision ? new Headers({'If-Match':revision}) : {etagDoesNotMatch:'*'},
    httpMetadata:{contentType:'application/json'}
  });
  if(!write)return json({error:'Another device synced first.'},409);
  return json({saved:records.length});
}

// Small per-isolate cache: avoids repeat provider trips across refreshes on this Worker.
// Successful results only; no secrets, errors, or partial results are cached.
const liveSearchEdgeCache = new Map();
async function webSearch(request,url,env) {
  if(request.method!=='POST')return json({error:'Method not allowed.'},405);
  if(request.headers.get('origin')!==url.origin || !request.headers.get('content-type')?.startsWith('application/json')){
    return json({error:'Open Studio directly to search.'},403);
  }
  const {query,key:browserKey}=await boundedJson(request);
  if(typeof query!=='string'||query.trim().length<2||query.length>180){
    return json({error:'Enter a valid search query.'},400);
  }
  // Prefer the account owner's Cloudflare secret. Never send it to the browser.
  const serverKey=typeof env?.TAVILY_API_KEY==='string'?env.TAVILY_API_KEY.trim():'';
  const key=serverKey||(typeof browserKey==='string'?browserKey.trim():'');
  if(!/^tvly-[a-zA-Z0-9_-]{10,190}$/.test(key)){
    return json({error:'Live research is not connected. Add a Cloudflare Worker secret named TAVILY_API_KEY, or enter a Tavily API key in Research.'},503);
  }
  const cacheKey=query.trim().toLowerCase().replace(/\s+/g,' ');
  const recent=liveSearchEdgeCache.get(cacheKey);
  if(recent && Date.now()-recent.checkedAt<30000) return json(recent.payload);
  // Retry short-lived network errors only. Never disguise an invalid key or depleted credits.
  let provider, networkError=null;
  for(let attempt=0;attempt<2;attempt++){
    try {
      provider=await fetch('https://api.tavily.com/search',{
        method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},
        body:JSON.stringify({query:query.trim(),search_depth:'basic',auto_parameters:false,max_results:6,include_answer:false,include_raw_content:false}),
        redirect:'follow',signal:AbortSignal.timeout(18000)
      });
      networkError=null;
      if([500,502,503,504].includes(provider.status) && attempt===0){
        await new Promise(resolve=>setTimeout(resolve,350));
        continue;
      }
      break;
    } catch(error) {
      networkError=error;
      if(attempt===0){await new Promise(resolve=>setTimeout(resolve,350));continue;}
    }
  }
  if(networkError || !provider){
    const timedOut=networkError?.name==='TimeoutError'||networkError?.name==='AbortError';
    return json({error:timedOut
      ? 'Tavily did not respond within the retry window. Current facts were not verified. Check Tavily status or try again.'
      : 'Cloudflare could not establish a connection to Tavily after retrying. Check Cloudflare Worker logs and Tavily status.'},502);
  }
  if(provider.status===401||provider.status===403)return json({error:'Tavily rejected the API key. Check that TAVILY_API_KEY is valid in Cloudflare secrets.'},401);
  if(provider.status===429||provider.status===432||provider.status===402)return json({error:'Tavily rate limit or free-plan credits reached. Current research is unavailable.'},429);
  if(!provider.ok)return json({error:'Tavily returned HTTP '+provider.status+'. No current information was verified.'},502);
  const data=await provider.json();
  const payload={results:(Array.isArray(data.results)?data.results:[]).slice(0,6).flatMap(item=>{
    try {
      const target=new URL(item.url);
      if(!['https:','http:'].includes(target.protocol)||target.username||target.password||target.href.length>1200)return [];
      return [{name:String(item.title||target.hostname).slice(0,180),link:target.href,source:target.hostname,note:String(item.content||'').slice(0,750),publishedDate:String(item.published_date||item.publishedDate||'').slice(0,50)}];
    } catch {return [];}
  })};
  if(payload.results.length){
    liveSearchEdgeCache.set(cacheKey,{checkedAt:Date.now(),payload});
    if(liveSearchEdgeCache.size>32)liveSearchEdgeCache.delete(liveSearchEdgeCache.keys().next().value);
  }
  return json(payload);
}

// Gemini and Workers AI share one authenticated endpoint. Keys stay server-side.
const GEMINI_DEFAULT_MODEL = 'gemini-3.5-flash-lite';
function geminiError(status, message) {
  const text=String(message||'').slice(0,220);
  if(status===401||status===403) return 'Gemini rejected the API key or this project does not have access to the model. Check the GEMINI_API_KEY secret.';
  if(status===429) return 'Gemini free-tier rate limit or quota reached. Try again after its allowance resets.';
  if(status===404) return 'Gemini model not available to this API project (HTTP 404). '+(text||'Check the GEMINI_MODEL setting and available models in Google AI Studio.');
  if(status===400) return 'Gemini rejected the request (HTTP 400). '+(text||'Check the model settings and API parameters.');
  return 'Gemini returned HTTP '+status+(text?': '+text:'');
}
function geminiRequest(input,env,model){
  const sys=input.messages.filter(m=>m.role==='system').map(m=>m.content).join('\n\n');
  const contents=[];
  for(const m of input.messages){
    if(m.role==='system')continue;
    const role=m.role==='assistant'?'model':'user';
    if(contents.length && contents[contents.length-1].role===role){
      contents[contents.length-1].parts.push({text:m.content});
    }else contents.push({role,parts:[{text:m.content}]});
  }
  const params={
    contents,
    generationConfig:{
      // Gemini 3.x models may reject legacy thinkingBudget and sampling options.
      // Use only the broadly supported output-token limit.
      maxOutputTokens:Math.max(512,Math.min(7500,Number(input.max_tokens)||900))
    }
  };
  if(sys)params.systemInstruction={parts:[{text:sys}]};
  const streaming=input.stream===true;
  return {
    url:'https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+(streaming?':streamGenerateContent?alt=sse':':generateContent'),
    body:JSON.stringify(params),streaming
  };
}
function geminiText(packet){
  return (packet?.candidates?.[0]?.content?.parts||[]).filter(p=>typeof p.text==='string' && !p.thought).map(p=>p.text).join('');
}
async function geminiReply(input,env) {
  if(!env?.GEMINI_API_KEY)return json({error:'Gemini is not connected. Add GEMINI_API_KEY as a Cloudflare secret.'},503);
  const model=typeof env.GEMINI_MODEL==='string'&&/^gemini-[a-zA-Z0-9.-]{4,70}$/.test(env.GEMINI_MODEL)?env.GEMINI_MODEL:GEMINI_DEFAULT_MODEL;
  const {url,body,streaming}=geminiRequest(input,env,model);
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),80000);
  let upstream;
  try{
    upstream=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':env.GEMINI_API_KEY},body,signal:controller.signal});
    if(!upstream.ok){
      clearTimeout(timeout);
      const errorData=await upstream.text().catch(()=> '');
      let message='';try{message=JSON.parse(errorData)?.error?.message||'';}catch{message=errorData;}
      return json({error:geminiError(upstream.status,message),provider:'gemini'},upstream.status===429?429:502);
    }
    if(!streaming){
      const data=await upstream.json();clearTimeout(timeout);
      const response=geminiText(data);
      if(!response.trim())return json({error:'Gemini completed without returning answer text.',provider:'gemini'},502);
      return json({response,provider:'gemini'});
    }
    if(!upstream.body){clearTimeout(timeout);return json({error:'Gemini returned an empty stream.',provider:'gemini'},502);}
    // Convert Gemini SSE events to the OpenAI-compatible SSE format Studio already consumes.
    const encoder=new TextEncoder();const decoder=new TextDecoder();
    let reader=upstream.body.getReader();
    let pending='';let gotText=false;let ended=false;
    const stream=new ReadableStream({
      async pull(control){
        try{
          while(true){
            const {value,done}=await reader.read();
            pending+=decoder.decode(value||new Uint8Array(),{stream:!done});
            const lines=pending.split(/\r?\n/);
            pending=done?'':lines.pop();
            for(const line of lines){
              if(!line.startsWith('data:'))continue;
              const payload=line.slice(5).trim();if(!payload||payload==='[DONE]')continue;
              let packet;try{packet=JSON.parse(payload);}catch{continue;}
              if(packet.error){
                control.enqueue(encoder.encode('data: '+JSON.stringify({error:{message:String(packet.error.message||'Gemini streaming error'),status:packet.error.status,code:packet.error.code}})+'\n\n'));
                ended=true;clearTimeout(timeout);control.close();return;
              }
              const part=geminiText(packet);
              if(part){gotText=true;control.enqueue(encoder.encode('data: '+JSON.stringify({choices:[{delta:{content:part}}]})+'\n\n'));}
              const finish=packet.candidates?.[0]?.finishReason;
              if(finish){
                control.enqueue(encoder.encode('data: '+JSON.stringify({choices:[{delta:{},finish_reason:finish==='MAX_TOKENS'?'length':'stop'}]})+'\n\n'));
              }
            }
            if(done){
              if(!gotText)control.enqueue(encoder.encode('data: '+JSON.stringify({error:{message:'Gemini finished without answer text.'}})+'\n\n'));
              control.enqueue(encoder.encode('data: [DONE]\n\n'));
              ended=true;clearTimeout(timeout);control.close();return;
            }
            if(gotText)return;
          }
        }catch(error){
          if(!ended){
            control.enqueue(encoder.encode('data: '+JSON.stringify({error:{message:error?.name==='AbortError'?'Gemini request timed out.':'Gemini streaming connection was interrupted.'}})+'\n\n'));
            clearTimeout(timeout);control.close();ended=true;
          }
        }
      },
      cancel(){ended=true;clearTimeout(timeout);controller.abort();reader.cancel().catch(()=>{});}
    });
    return new Response(stream,{headers:{'Content-Type':'text/event-stream; charset=utf-8','Cache-Control':'no-store, no-transform','X-Studio-AI-Provider':'gemini'}});
  }catch(error){
    clearTimeout(timeout);
    return json({error:error?.name==='AbortError'?'Gemini request timed out.':'Could not connect to Gemini: '+String(error?.message||error).slice(0,140),provider:'gemini'},502);
  }
}
async function cloudflareReply(input,ai) {
  if(!ai)return json({error:'Cloudflare Workers AI binding is unavailable.',provider:'cloudflare'},503);
  const messages=input.messages.map(m=>({role:m.role,content:m.content}));
  const max_tokens=Math.max(64,Math.min(7500,Number(input.max_tokens)||900));
  const started=Date.now();
  try {
    const fast=input.speed_tier==='fast';
    const model=fast?'@cf/qwen/qwen3.8-27b':'@cf/google/gemma-4-26b-a4b-it';
    console.log('studio_ai_start',JSON.stringify({provider:'cloudflare',model,stream:input.stream===true,max_tokens,messages:messages.length}));
    const result=await ai.run(model,{messages,chat_template_kwargs:{enable_thinking:false},...(input.stream===true?{stream:true}:{}),max_completion_tokens:max_tokens,temperature:Math.max(0,Math.min(1,Number(input.temperature)||0.35))});
    console.log('studio_ai_ready_ms',Date.now()-started);
    if(input.stream===true && result instanceof ReadableStream)return new Response(result,{headers:{'Content-Type':'text/event-stream; charset=utf-8','Cache-Control':'no-store, no-transform','X-Studio-AI-Provider':'cloudflare'}});
    const response=result?.choices?.[0]?.message?.content ?? result?.response;
    if(typeof response!=='string'||!response.trim())return json({error:'Cloudflare AI returned no text.',provider:'cloudflare',code:'empty_ai_reply'},502);
    return json({response,provider:'cloudflare'});
  }catch(error){
    const message=String(error?.message||error).slice(0,180);
    console.error('studio_ai_error_ms',Date.now()-started,message);
    return json({error:'Cloudflare AI request failed: '+message,provider:'cloudflare',code:/4006|10,000 neurons|daily free allocation/i.test(message)?'quota_exceeded':'provider_error'},/4006/.test(message)?429:502);
  }
}
async function hostedChat(request,env) {
  if(request.method!=='POST')return json({error:'Use POST for AI requests.'},405);
  const raw=await request.text();
  if(raw.length>30000)return json({error:'AI request is too large.'},413);
  let input;
  try{input=JSON.parse(raw);}catch{return json({error:'Invalid AI request.'},400);}
  if(!Array.isArray(input.messages)||input.messages.length<1||input.messages.length>12||input.messages.some(m=>!m||!['system','user','assistant'].includes(m.role)||typeof m.content!=='string'||m.content.length>16000))return json({error:'Invalid AI messages.'},400);
  if(input.builder_backup==='gemini'){
    return cloudflareReply(input,env?.AI);
  }
  if(input.builder_backup==='cloudflare'){
    // A stream error from the fast Workers AI model gets one attempt on the quality model.
    return cloudflareReply({...input,speed_tier:'quality'},env?.AI);
  }
  // Prefer Gemini while its free quota is available: avoids wasting Cloudflare neurons on large website builds.
  // If Gemini cannot accept the request, allow a Cloudflare fallback where configured.
  if(env?.GEMINI_API_KEY){
    const primary=await geminiReply(input,env);
    if(primary.ok || !env.AI)return primary;
    // Do not retry a quota-exhausted provider through another costly sequence without need.
    console.warn('studio_gemini_fallback',primary.status);
    const secondary=await cloudflareReply(input,env.AI);
    if(secondary.ok)return secondary;
    return primary;
  }
  return cloudflareReply(input,env?.AI);
}

const studioApp = {
  async fetch(request,env){
    const url=new URL(request.url);
    try {
      // The owner-only Sites access policy protects the page and its storage API.
      if(url.pathname==='/api/ai')return await hostedChat(request,env);
      if(url.pathname==='/api/web-search')return await webSearch(request,url,env);
      if(url.pathname==='/api/project-sync')return await sync(request,env.BUCKET,url);
      const path=url.pathname==='/'?'/index.html':url.pathname;
      if(request.method==='GET' && Object.hasOwn(assets,path))return new Response(assets[path],{
        headers:{
          'Content-Type':mime[path.split('.').at(-1)]+'; charset=utf-8',
          'Cache-Control':'no-cache',
          'X-Content-Type-Options':'nosniff'
        }
      });
      return new Response('Not found',{status:404});
    } catch(error){return json({error:error instanceof SyntaxError?'Invalid project data.':error.message||'Private sync is unavailable.'},400);}
  }
};

const encoder = new TextEncoder();
const noStore = {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','X-Robots-Tag':'noindex'};
const status = (message,code,extra={}) => new Response(message,{status:code,headers:{...noStore,'Content-Type':'text/plain; charset=utf-8',...extra}});

async function matches(left,right) {
  const [leftHash,rightHash] = await Promise.all([
    crypto.subtle.digest('SHA-256',encoder.encode(left)),
    crypto.subtle.digest('SHA-256',encoder.encode(right))
  ]);
  const a=new Uint8Array(leftHash),b=new Uint8Array(rightHash);
  let diff=0;
  for(let i=0;i<a.length;i++)diff |= a[i]^b[i];
  return diff===0;
}

async function authorised(request,password) {
  const header=request.headers.get('authorization')||'';
  if(!header.startsWith('Basic ')||header.length>800)return false;
  try{return matches(atob(header.slice(6)),'studio:'+password);}
  catch{return false;}
}

function databaseStorage(db) {
  if(!db)throw new Error('Project sync storage is not configured.');
  return {
    async get(){
      const row=await db.prepare('SELECT revision, projects FROM studio_projects WHERE id = 1').first();
      if(!row)return null;
      return {httpEtag:'"'+row.revision+'"',json:async()=>JSON.parse(row.projects)};
    },
    async put(_key,body,options){
      if(encoder.encode(body).length>1_500_000)throw new Error('Independent sync supports 1.5 MB of drafts. Download a backup to retain the full collection.');
      const revision=crypto.randomUUID().replaceAll('-','');
      const old=options.onlyIf instanceof Headers?options.onlyIf.get('if-match')?.slice(1,-1):undefined;
      const operation=old
        ?db.prepare('UPDATE studio_projects SET revision = ?, projects = ? WHERE id = 1 AND revision = ?').bind(revision,body,old)
        :db.prepare('INSERT OR IGNORE INTO studio_projects (id, revision, projects) VALUES (1, ?, ?)').bind(revision,body);
      const result=await operation.run();
      return result.meta.changes===1?{httpEtag:'"'+revision+'"'}:null;
    }
  };
}

const reviewToken = /^[a-f0-9]{64}$/;
const reviewDays = 7 * 86400000;
const reviewJson = (value,code=200) => Response.json(value,{status:code,headers:noStore});
const escapeReview = value => value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function clientReview(request,url,db,token,owner) {
  const failure=(error,code)=>reviewJson({error},code);
  if(!db)return failure('Client review needs the Studio database binding.',503);
  const now=Date.now();
  try {
    if(owner && !token && request.method==='POST'){
      if(request.headers.get('origin')!==url.origin)return failure('Open Studio directly to create a review.',403);
      const {title,html}=await boundedJson(request);
      if(typeof title!=='string'||title.length>200||typeof html!=='string'||!html.trim()||html.length>450000)return failure('Invalid project snapshot.',400);
      await db.prepare('CREATE TABLE IF NOT EXISTS studio_client_reviews (token TEXT PRIMARY KEY, title TEXT NOT NULL, html TEXT NOT NULL, expires INTEGER NOT NULL, decision TEXT, notes TEXT)').run();
      await db.prepare('DELETE FROM studio_client_reviews WHERE expires <= ?').bind(now).run();
      const key=crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');
      await db.prepare('INSERT INTO studio_client_reviews (token,title,html,expires) VALUES (?,?,?,?)').bind(key,title,html,now+reviewDays).run();
      return reviewJson({link:url.origin+'/review/'+key},201);
    }
    if(!reviewToken.test(token))return failure('Review link unavailable.',404);
    if(owner && request.method==='DELETE'){
      if(request.headers.get('origin')!==url.origin)return failure('Open Studio directly to revoke a review.',403);
      const result=await db.prepare('UPDATE studio_client_reviews SET expires = ? WHERE token = ? AND expires > ?').bind(now,token,now).run();
      return reviewJson({revoked:Boolean(result.meta.changes)});
    }
    const row=await db.prepare('SELECT title,html,decision,notes FROM studio_client_reviews WHERE token = ? AND expires > ?').bind(token,now).first();
    if(!row)return failure('Review link unavailable or expired.',404);
    if(owner && request.method==='GET')return reviewJson({decision:row.decision,notes:row.notes,...(row.decision==='approved' && url.searchParams.get('snapshot')==='1'?{html:row.html}:{})});
    if(!owner && request.method==='POST'){
      if(request.headers.get('origin')!==url.origin)return failure('Open the review link directly.',403);
      if(Number(request.headers.get('content-length'))>12000)return failure('Feedback is too long.',413);
      const form=new URLSearchParams(await request.text());
      const decision=form.get('decision'),notes=(form.get('notes')||'').trim();
      if(!['approved','changes'].includes(decision)||notes.length>1500||(decision==='changes'&&!notes))return failure('Choose approval or enter notes for requested changes.',400);
      const result=await db.prepare('UPDATE studio_client_reviews SET decision = ?, notes = ? WHERE token = ? AND expires > ? AND decision IS NULL').bind(decision,notes,token,now).run();
      if(!result.meta.changes)return failure('This review already has a response or has expired.',409);
      return new Response(null,{status:303,headers:{...noStore,Location:url.pathname,'Referrer-Policy':'no-referrer'}});
    }
    if(owner || request.method!=='GET')return failure('Method not allowed.',405);
    const title=escapeReview(row.title);
    const snapshot=escapeReview('<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; img-src data: blob:; font-src data:; form-action \'none\'; base-uri \'none\'">'+row.html);
    const feedback=row.decision?'<p>Your response was recorded.</p>':'<form method="post"><label for="notes">Review notes</label><textarea id="notes" name="notes" rows="3" maxlength="1500"></textarea><button name="decision" value="approved">Approve draft</button> <button name="decision" value="changes">Request changes</button></form>';
    return new Response('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review '+title+'</title><style>body{background:#f3e8d9;color:#30241e;font:16px system-ui;margin:16px}iframe{width:100%;height:65vh;border:1px solid #cbb49d;background:#fff}textarea{display:block;width:min(100%,36rem);margin:8px 0}button{padding:10px;margin:4px 0}</style><h1>Review '+title+'</h1><p>This snapshot is for visual review. Forms and scripts are disabled.</p><iframe title="Website draft" sandbox srcdoc="'+snapshot+'"></iframe>'+feedback+'</html>',{headers:{...noStore,'Content-Type':'text/html; charset=utf-8','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; img-src data: blob:; font-src data:; frame-ancestors 'none'; form-action 'self'; base-uri 'none'"}});
  }catch{return failure('Client review storage is unavailable.',503);}
}

async function launchRecord(request,url,db,id){
  if(!db)return reviewJson({error:'Studio database is unavailable.'},503);
  if(!['GET','PUT'].includes(request.method))return reviewJson({error:'Method not allowed.'},405);
  if(request.method==='PUT'&&request.headers.get('origin')!==url.origin)return reviewJson({error:'Open Studio directly to save.'},403);
  try{
    await db.prepare('CREATE TABLE IF NOT EXISTS studio_launch_records (project_id TEXT PRIMARY KEY, record TEXT NOT NULL)').run();
    if(request.method==='GET'){
      const row=await db.prepare('SELECT record FROM studio_launch_records WHERE project_id = ?').bind(id).first();
      return row?reviewJson({record:JSON.parse(row.record)}):reviewJson({error:'No launch record saved for this project.'},404);
    }
    const {checks,intake,handoff,inline,review}=await boundedJson(request);
    const validFields=value=>value===null||(value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length<=20&&Object.values(value).every(text=>typeof text==='string'&&text.length<=2000));
    const reviewPath=typeof review==='string'&&review.startsWith(url.origin+'/review/')&&reviewToken.test(review.slice(url.origin.length+8));
    if(!(checks===null||Array.isArray(checks)&&checks.length<=20&&checks.every(n=>Number.isInteger(n)&&n>=0&&n<20))||
      !validFields(intake)||!validFields(handoff)||!(inline===null||typeof inline==='boolean')||!(review===null||review===''||reviewPath)){
      return reviewJson({error:'Invalid launch record.'},400);
    }
    await db.prepare('INSERT INTO studio_launch_records (project_id,record) VALUES (?,?) ON CONFLICT(project_id) DO UPDATE SET record=excluded.record').bind(id,JSON.stringify({checks,intake,handoff,inline,review})).run();
    return reviewJson({saved:true});
  }catch{return reviewJson({error:'Could not access the launch record.'},503);}
}

async function projectImage(request,url,ai) {
  if(request.method!=='POST')return reviewJson({error:'Method not allowed.'},405);
  if(request.headers.get('origin')!==url.origin)return reviewJson({error:'Open Studio directly to generate an image.'},403);
  if(!ai)return reviewJson({error:'Cloudflare Workers AI is not configured.'},503);
  let input;
  try {input=await boundedJson(request);}
  catch {return reviewJson({error:'Invalid image request.'},400);}
  const description=typeof input?.description==='string' ? input.description.trim() : '';
  if(!description || description.length>1200)return reviewJson({error:'Enter a project description up to 1,200 characters.'},400);
  const kind=typeof input.kind==='string' ? input.kind.slice(0,60) : 'project';
  const prompt='Generate a single landscape concept image for this '+kind+'. Use photography or illustration as appropriate to the subject. Show the relevant scene or object with a clear focal point. Keep text, logos, watermarks and UI mockups out of the image. Project brief: '+description;
  try {
    const result=await ai.run('@cf/black-forest-labs/flux-1-schnell',{prompt,steps:4});
    const image=result?.image;
    if(typeof image!=='string'||image.length>2_000_000||!image.startsWith('/9j/'))throw new Error('Invalid image.');
    const bytes=Uint8Array.from(atob(image),character=>character.charCodeAt(0));
    return new Response(bytes,{headers:{...noStore,'Content-Type':'image/jpeg'}});
  }catch{
    return reviewJson({error:'The image generator is unavailable. Check Workers AI usage and try again.'},502);
  }
}

export default {
  async fetch(request,env) {
    const password=env.STUDIO_PASSWORD;
    if(typeof password!=='string'||!(/^[!-~]{24,128}$/).test(password))return status('Private Studio setup is incomplete.',503);
    const url=new URL(request.url);
    const shared=url.pathname.match(/^\/review\/([a-f0-9]{64})$/);
    if(shared)return clientReview(request,url,env.DB,shared[1],false);
    if(!await authorised(request,password)){
      return status('Sign in to your private Elevanta Studio.',401,{'WWW-Authenticate':'Basic realm="Elevanta Creative Studio", charset="UTF-8"'});
    }
    const pathname=url.pathname;
    if(pathname==='/api/project-image')return projectImage(request,url,env.AI);
    const launch=pathname.match(/^\/api\/launch-record\/([a-zA-Z0-9_-]{1,80})$/);
    if(launch)return launchRecord(request,url,env.DB,launch[1]);
    if(pathname==='/api/client-review'||pathname.startsWith('/api/client-review/')){
      return clientReview(request,url,env.DB,pathname.slice('/api/client-review/'.length),true);
    }
    const bindings=pathname==='/api/project-sync'?{BUCKET:databaseStorage(env.DB)}:pathname==='/api/ai'?{AI:env.AI,GEMINI_API_KEY:env.GEMINI_API_KEY,GEMINI_MODEL:env.GEMINI_MODEL}:pathname==='/api/web-search'?{TAVILY_API_KEY:env.TAVILY_API_KEY}:{};
    const response=await studioApp.fetch(request,bindings);
    const headers=new Headers(response.headers);
    for(const [key,value] of Object.entries(noStore))headers.set(key,value);
    headers.set('X-Frame-Options','DENY');
    headers.set('Referrer-Policy','no-referrer');
    return new Response(response.body,{status:response.status,statusText:response.statusText,headers});
  }
};
